size(110);
draw(Arc((0,0),1,0,300),heavycyan);
draw(Arc((0,0),1,300,360),linetype("2 4"));
draw((1,0)--(0,0)--(.5,-.5*sqrt(3)));
label("18",(.5,0),S); label("$300^\circ$",(0,0),NW);
[/asy]

